// 🎯 Game State: Track user & computer scores
let userScore = 0;
let computerScore = 0;

// 🎯 Cache DOM elements
const userScoreSpan = document.getElementById('user-score');
const computerScoreSpan = document.getElementById('computer-score');
const resultDiv = document.querySelector('.result');
const choices = document.querySelectorAll('.choice');

// 🎯 Get Computer's Random Choice
const getComputerChoice = () => {
    const choices = ['rock', 'paper', 'scissors'];
    return choices[Math.floor(Math.random() * choices.length)];
};

// 🎯 Convert choice to Title Case for UI
const formatChoice = choice => choice.charAt(0).toUpperCase() + choice.slice(1);

// 🎯 Update UI and Apply Effects
const updateGameStatus = (userChoice, computerChoice, message, statusClass) => {
    resultDiv.innerHTML = `<p>${message}</p>`;
    applyEffect(userChoice, statusClass);
};

// 🎯 Apply Temporary Visual Effect
const applyEffect = (choice, effectClass) => {
    const selectedChoice = document.getElementById(choice);
    selectedChoice.classList.add(effectClass);
    setTimeout(() => selectedChoice.classList.remove(effectClass), 300);
};

// 🎯 Handle Game Outcome
const playRound = (userChoice) => {
    const computerChoice = getComputerChoice();

    const outcomes = {
        win: [`rockscissors`, `paperrock`, `scissorspaper`],
        lose: [`rockpaper`, `scissorsrock`, `paperscissors`],
    };

    if (outcomes.win.includes(userChoice + computerChoice)) {
        userScore++;
        userScoreSpan.textContent = userScore;
        updateGameStatus(userChoice, computerChoice, 
            `${formatChoice(userChoice)} (User) beats ${formatChoice(computerChoice)} (Computer). <strong>You Win! 🎉</strong>`, 
            'winningStyles'
        );
    } else if (outcomes.lose.includes(userChoice + computerChoice)) {
        computerScore++;
        computerScoreSpan.textContent = computerScore;
        updateGameStatus(userChoice, computerChoice, 
            `${formatChoice(computerChoice)} (Computer) beats ${formatChoice(userChoice)} (User). <strong>You Lose! 😞</strong>`, 
            'losingStyles'
        );
    } else {
        updateGameStatus(userChoice, computerChoice, 
            `It's a Draw! You both chose ${formatChoice(userChoice)}. 🤝`, 
            'drawStyles'
        );
    }
};

// 🎯 Add Event Listeners to Choices
choices.forEach(choice => choice.addEventListener('click', () => playRound(choice.id)));
